// minimal all-to-all triplet STDP for one synapse, event-driven
function tripletSynapse({A3p = 6.2e-3, A2m = 7e-3, tauP = 16.8, tauM = 33.7, tauY = 125} = {}) {
  let w = 0.5, r1 = 0, o1 = 0, o2 = 0, last = 0;
  const decay = (t) => {
    const g = t - last; last = t;
    r1 *= Math.exp(-g / tauP); o1 *= Math.exp(-g / tauM); o2 *= Math.exp(-g / tauY);
  };
  return {
    pre(t)  { decay(t); w -= A2m * o1; r1 += 1; },
    post(t) { decay(t); w += A3p * r1 * o2; o1 += 1; o2 += 1; }, // o2 read before update
    get w() { return w; },
  };
}
